private static void constructLinkedList() {
    int remainder = rawString.length() % 4;
    int nodeCount;
    if(remainder == 0) {
        nodeCount = rawString.length() / 4;
    } else {
        nodeCount = rawString.length() / 4 + 1;
    }
    for(int i = 0; i < 4 - remainder; i++) {
        rawString += '\0';
    }
    headNode = new Node("");
    Node currentNode = headNode;
    for(int i = 0; i < nodeCount; i++) {
        currentNode.setNextNode(new Node(rawString.substring(i * 4, i * 4 + 4)));
        currentNode.getNextNode().setPreviousNode(currentNode);
        currentNode = currentNode.getNextNode();
    }
}

private static boolean matchString() {
    int matchIndex = 0;
    Node currentNode = headNode.getNextNode();
    int charIndex = 0;
    Node matchNode = null;
    int matchCharIndex = 0;
    while(currentNode != null) {
        for(charIndex = 0; charIndex < 4; charIndex++) {
            if(currentNode.getNodeString().charAt(charIndex) == matchString.charAt(0)) {
                matchNode = currentNode;
                matchCharIndex = charIndex;
                for(matchIndex = 0; matchIndex < matchString.length(); matchIndex++) {
                    if(matchCharIndex >= 4) {
                        matchNode = matchNode.getNextNode();
                        matchCharIndex = 0;
                    }
                    if(matchNode.getNodeString().charAt(matchCharIndex) != matchString.charAt(matchIndex)) {
                        break;
                    }
                    matchCharIndex++;
                }
                if(matchIndex == matchString.length()) {
                    return true;
                }
            }
        }
        currentNode = currentNode.getNextNode();
    }
    return false;
}
